<?php
require_once '_bootstrap.php';require_admin_permission('catalog.manage');$db=admin_db();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';$id=(int)($_POST['id']??0);$name=trim($_POST['name']??'');$description=trim($_POST['description']??'');
 if(in_array($action,['create','update'],true)){if($name==='')redirect_with_message('transports.php','Transport category name is required.');if($action==='create'){$s=$db->prepare('INSERT INTO transport_categories(name,description) VALUES(?,?)');$s->bind_param('ss',$name,$description);}else{$s=$db->prepare('UPDATE transport_categories SET name=?,description=? WHERE id=?');$s->bind_param('ssi',$name,$description,$id);}if(!$s->execute())redirect_with_message('transports.php','That transport category already exists.');admin_audit($db,$action,'transport',(string)($id?:$db->insert_id),$name);}
 elseif(in_array($action,['enable','disable'],true)){$status=$action==='enable'?'active':'disabled';$s=$db->prepare('UPDATE transport_categories SET status=? WHERE id=?');$s->bind_param('si',$status,$id);$s->execute();}
 elseif($action==='delete'){$s=$db->prepare('SELECT COUNT(*) total FROM packages WHERE transport_category_id=?');$s->bind_param('i',$id);$s->execute();if((int)$s->get_result()->fetch_assoc()['total'])redirect_with_message('transports.php','This category is used by packages. Disable it instead.');$s=$db->prepare('DELETE FROM transport_categories WHERE id=?');$s->bind_param('i',$id);$s->execute();}
 redirect_with_message('transports.php','Transport category updated.');}
$edit=null;if(!empty($_GET['edit'])){$id=(int)$_GET['edit'];$s=$db->prepare('SELECT * FROM transport_categories WHERE id=?');$s->bind_param('i',$id);$s->execute();$edit=$s->get_result()->fetch_assoc();}$search=admin_search();$condition=admin_search_condition($db,['t.name','t.description','t.status'],$search);$where=$condition?' WHERE '.$condition:'';$pagination=admin_paginate($db,'SELECT COUNT(*) total FROM transport_categories t'.$where);$items=$db->query('SELECT t.*,COUNT(p.id) package_count FROM transport_categories t LEFT JOIN packages p ON p.transport_category_id=t.id'.$where.' GROUP BY t.id ORDER BY t.name LIMIT '.$pagination['limit'].' OFFSET '.$pagination['offset']);$pageTitle='Transport Categories';include '_header.php';?>
<div class="page-head"><div><span>Travel operations</span><h1>Transport Categories</h1><p>Create reusable transport options for tour packages.</p></div></div>
<section class="panel form-panel"><div class="panel-head"><h2><?php echo $edit?'Edit transport':'Add transport';?></h2><?php if($edit):?><a href="transports.php">Cancel</a><?php endif;?></div><form class="admin-form" method="post"><?php echo csrf_input();?><input type="hidden" name="action" value="<?php echo $edit?'update':'create';?>"><input type="hidden" name="id" value="<?php echo (int)($edit['id']??0);?>"><label>Name<input name="name" value="<?php echo e($edit['name']??'');?>" required></label><label>Description<input name="description" value="<?php echo e($edit['description']??'');?>"></label><div class="form-actions"><button><i class="fa-solid fa-floppy-disk"></i>Save transport</button></div></form></section>
<section class="panel"><div class="table-wrap"><table><thead><tr><th>Transport</th><th>Description</th><th>Packages</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php while($t=$items->fetch_assoc()):?><tr><td><strong><?php echo e($t['name']);?></strong></td><td><?php echo e($t['description']);?></td><td><?php echo (int)$t['package_count'];?></td><td><span class="pill"><?php echo e($t['status']);?></span></td><td><div class="action-row"><a class="icon-btn" href="?edit=<?php echo (int)$t['id'];?>" title="Edit"><i class="fa-solid fa-pen"></i></a><form method="post"><?php echo csrf_input();?><input type="hidden" name="id" value="<?php echo (int)$t['id'];?>"><input type="hidden" name="action" value="<?php echo $t['status']==='active'?'disable':'enable';?>"><button class="icon-btn status-toggle <?php echo $t['status']==='active'?'is-on':'is-off';?>" title="<?php echo $t['status']==='active'?'Disable':'Enable';?>"><i class="fa-solid fa-toggle-<?php echo $t['status']==='active'?'on':'off';?>"></i></button></form><form method="post" onsubmit="return confirm('Delete this unused transport category?')"><?php echo csrf_input();?><input type="hidden" name="id" value="<?php echo (int)$t['id'];?>"><input type="hidden" name="action" value="delete"><button class="icon-btn danger-icon" title="Delete"><i class="fa-solid fa-trash"></i></button></form></div></td></tr><?php endwhile;?></tbody></table></div><?php admin_pagination($pagination);?></section><?php include '_footer.php';?>
